mapper.select:
SELECT id, user_id, daily_mission_id, progress, is_completed, is_claimed, assigned_date
FROM user_daily_mission
WHERE user_id = #{userId} AND assigned_date = #{date}

mapper.update:
UPDATE user_daily_mission
SET progress = #{progress},
    is_completed = #{isCompleted}
WHERE id = #{id}

UPDATE user_daily_mission
SET is_claimed = true
WHERE id = #{id}
